    out = [row[:] for row in grid]

    # Find repeated color strip, either horizontal or vertical.
    strips = []
    for r in range(h):
        cols = [c for c, v in enumerate(grid[r]) if v]
        if len(cols) >= 2:
            strips.append(("row", r, cols))
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c]]
        if len(rows) >= 2:
            strips.append(("col", c, rows))

    # The palette is the straight multi-color stripe with colors repeated
    # consistently in its perpendicular direction.
    palette = None
    for orient, fixed, varying in strips:
        vals = [grid[fixed][v] if orient == "row" else grid[v][fixed] for v in varying]
        if len(set(vals)) >= 3 and len(varying) >= 3:
            palette = (orient, fixed, varying, vals)
            break
    if palette is None:
        return out

    orient, fixed, varying, seq = palette
    if orient == "row":
        # Confirm the colors in the strip repeat on adjacent rows.
        r0 = fixed
        r1 = fixed
        while r1 + 1 < h and all(grid[r1 + 1][c] == grid[fixed][c] for c in varying):
            r1 += 1
        r0 = fixed
        while r0 - 1 >= 0 and all(grid[r0 - 1][c] == grid[fixed][c] for c in varying):
            r0 -= 1
        for r in range(r0, r1 + 1):
            for c in varying:
                out[r][c] = 0
    else:
        c0 = fixed
        c1 = fixed
        while c1 + 1 < w and all(grid[r][c1 + 1] == grid[r][fixed] for r in varying):
            c1 += 1
        while c0 - 1 >= 0 and all(grid[r][c0 - 1] == grid[r][fixed] for r in varying):
            c0 -= 1
        for r in varying:
            for c in range(c0, c1 + 1):
                out[r][c] = 0

    # The object whose color occurs in the palette is the template.
    target = seq[len(seq) // 2] if 1 not in seq else 1
    coords = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == target]
    # Exclude palette cells from the template.
    coords = [(r, c) for r, c in coords if out[r][c] != 0]
    minr, maxr = min(r for r, c in coords), max(r for r, c in coords)
    minc, maxc = min(c for r, c in coords), max(c for r, c in coords)
    shape = [(r - minr, c - minc) for r, c in coords]
    dh, dw = maxr - minr + 1, maxc - minc + 1
